-- ============================================================
-- AI School - clean rebuild of the customer-service data (2026-10-09, v2)
-- Wipes: leads, their stage events / call attempts, teacher slots, WhatsApp
-- message log.  Keeps: users, finance, subscriptions (re-linked by phone),
-- teachers, WhatsApp templates and settings.
-- One row per booking: a phone can hold several (siblings / repeat attendance).
--   * every lecture of the free-lectures workbook (246) is a booking with a phone
--     linked from the «الحجوزات» sheet / customer files (6 nameless ones = «محاضرة مأجلة»)
--   * every row of the «الحجوزات» sheet is a booking; the ones missing from the
--     free-lectures workbook stay pending for manual attendance
--   * old «تم الحجز» customers without any row stay in الحجوزات as pending (review)
-- attended -> stage interested (عملاء مهتمون); did not attend -> attendance_recorded;
-- pending -> booked.   TAKE A DB BACKUP FIRST.
-- ============================================================
BEGIN;
DELETE FROM whatsapp_message_log;
DELETE FROM crm_lead_call_attempts;
DELETE FROM crm_lead_stage_events;
DELETE FROM crm_teacher_slots;
DELETE FROM crm_leads;

