-- subscriptions keep their own phone: re-link them to the rebuilt leads
UPDATE subscriptions s SET lead_id = (SELECT l.id FROM crm_leads l WHERE l.phone = s.phone ORDER BY l.created_at LIMIT 1);

-- checks
SELECT count(*) AS rows, count(DISTINCT phone) FILTER (WHERE phone NOT LIKE 'UNKNOWN%') AS real_phones,
       count(*) FILTER (WHERE attended IS TRUE) AS attended,
       count(*) FILTER (WHERE attended IS FALSE) AS not_attended,
       count(*) FILTER (WHERE stage = 'booked') AS pending,
       count(*) FILTER (WHERE phone LIKE 'UNKNOWN%') AS no_phone
FROM crm_leads;
COMMIT;
